                    _ = bun.handleOom(dest.append(allocator, Property{ .@"border-image-source" = mut_source.* }));
                    _ = bun.bits.insert(BorderImageProperty, (&self.flushed_properties), BorderImageProperty.@"border-image-source");
                }
                if (slice) |s| {
                    _ = &s;
                    _ = bun.handleOom(dest.append(allocator, Property{ .@"border-image-slice" = s }));
                    _ = bun.bits.insert(BorderImageProperty, (&self.flushed_properties), BorderImageProperty.@"border-image-slice");
