                    _ = &w;
                    _ = bun.handleOom(dest.append(allocator, Property{ .@"border-image-width" = w }));
                    _ = bun.bits.insert(BorderImageProperty, (&self.flushed_properties), BorderImageProperty.@"border-image-width");
                }
                if (outset) |o| {
                    _ = &o;
                    _ = bun.handleOom(dest.append(allocator, Property{ .@"border-image-outset" = o }));
                    _ = bun.bits.insert(BorderImageProperty, (&self.flushed_properties), BorderImageProperty.@"border-image-outset");
                }
                if (repeat) |r| {
                    _ = &r;
                    _ = bun.handleOom(dest.append(allocator, Property{ .@"border-image-repeat" = r }));
                    _ = bun.bits.insert(BorderImageProperty, (&self.flushed_properties), BorderImageProperty.@"border-image-repeat");
                }
            }
            self.vendor_prefix = VendorPrefix{  };
    }
